import type { Column, RowData, SortDirection } from '@tanstack/react-table';
import { ArrowDownIcon, ArrowUpIcon, ChevronsUpDownIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export type DataTableColumnHeaderProps<TData extends RowData, TValue> = {
    column: Column<TData, TValue>;
    children: ReactNode;
    className?: string;
};

const sortIcons: Record<SortDirection, typeof ArrowUpIcon> = {
    asc: ArrowUpIcon,
    desc: ArrowDownIcon,
};

/**
 * The sort control of a header cell. `DataTable` wraps every sortable column in
 * it, so a column definition only supplies its title. A column that renders its
 * own header control should set `enableSorting: false` to avoid nested buttons.
 *
 * The sort state itself is announced through `aria-sort` on the header cell,
 * which `DataTable` owns.
 */
export function DataTableColumnHeader<TData extends RowData, TValue>({
    column,
    children,
    className,
}: DataTableColumnHeaderProps<TData, TValue>) {
    const sorted = column.getIsSorted();
    const SortIcon = sorted ? sortIcons[sorted] : ChevronsUpDownIcon;

    return (
        <Button
            variant="ghost"
            size="sm"
            className={cn('-mx-2.5 font-medium', className)}
            onClick={column.getToggleSortingHandler()}
        >
            {children}
            <SortIcon
                aria-hidden="true"
                className={cn('text-muted-foreground', !sorted && 'opacity-50')}
            />
        </Button>
    );
}

import type { Column, RowData } from '@tanstack/react-table';
import { ListFilter } from 'lucide-react';
import type { ReactElement } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuCheckboxItem,
    DropdownMenuContent,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Separator } from '@/components/ui/separator';

export type DataTableFilterOption = {
    value: string;
    label: string;
};

export type DataTableFacetedFilterProps<TData extends RowData> = {
    column: Column<TData, unknown>;
    label: string;
    options: DataTableFilterOption[];
};

function selectedValues<TData extends RowData>(
    column: Column<TData, unknown>,
): string[] {
    const value = column.getFilterValue();

    return Array.isArray(value) ? (value as string[]) : [];
}

export function DataTableFacetedFilter<TData extends RowData>({
    column,
    label,
    options,
}: DataTableFacetedFilterProps<TData>): ReactElement {
    const selected = selectedValues(column);

    const toggle = (value: string, checked: boolean): void => {
        const next = checked
            ? [...selected, value]
            : selected.filter((item) => item !== value);

        column.setFilterValue(next.length > 0 ? next : undefined);
    };

    return (
        <DropdownMenu>
            <DropdownMenuTrigger
                render={
                    <Button
                        className="border-dashed"
                        size="sm"
                        variant="outline"
                    >
                        <ListFilter aria-hidden="true" />
                        {label}

                        {selected.length > 0 ? (
                            <>
                                <Separator
                                    className="mx-0.5 h-3.5"
                                    orientation="vertical"
                                />
                                {options
                                    .filter((option) =>
                                        selected.includes(option.value),
                                    )
                                    .map((option) => (
                                        <Badge
                                            key={option.value}
                                            size="sm"
                                            variant="secondary"
                                        >
                                            {option.label}
                                        </Badge>
                                    ))}
                            </>
                        ) : null}
                    </Button>
                }
            />

            <DropdownMenuContent align="start" className="w-44">
                {options.map((option) => (
                    <DropdownMenuCheckboxItem
                        checked={selected.includes(option.value)}
                        key={option.value}
                        onCheckedChange={(checked) => {
                            toggle(option.value, checked);
                        }}
                    >
                        {option.label}
                    </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

import type { RowData, Table as TableInstance } from '@tanstack/react-table';
import { X } from 'lucide-react';
import type { ReactElement } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import type { DataTableFilterOption } from './data-table-faceted-filter';
import { DataTableFacetedFilter } from './data-table-faceted-filter';

export type DataTableFilterDef = {
    columnId: string;
    label: string;
    options: DataTableFilterOption[];
};

export type DataTableFiltersProps<TData extends RowData> = {
    table: TableInstance<TData>;
    filters: DataTableFilterDef[];
    label?: string;
    resetLabel?: string;
    className?: string;
};

export function DataTableFilters<TData extends RowData>({
    table,
    filters,
    label = 'Фильтры',
    resetLabel = 'Сбросить',
    className,
}: DataTableFiltersProps<TData>): ReactElement {
    const isFiltered = table.getState().columnFilters.length > 0;

    return (
        // biome-ignore lint/a11y/useSemanticElements: a fieldset brings legend semantics and min-content sizing to a toolbar row
        <div
            aria-label={label}
            className={cn('flex flex-wrap items-center gap-2', className)}
            role="group"
        >
            {filters.map((filter) => {
                const column = table.getColumn(filter.columnId);

                if (!column) {
                    return null;
                }

                return (
                    <DataTableFacetedFilter
                        column={column}
                        key={filter.columnId}
                        label={filter.label}
                        options={filter.options}
                    />
                );
            })}

            {isFiltered ? (
                <Button
                    onClick={() => table.resetColumnFilters()}
                    size="sm"
                    type="button"
                    variant="ghost"
                >
                    {resetLabel}
                    <X />
                </Button>
            ) : null}
        </div>
    );
}

import type { RowData, Table } from '@tanstack/react-table';
import {
    ChevronLeftIcon,
    ChevronRightIcon,
    ChevronsLeftIcon,
    ChevronsRightIcon,
} from 'lucide-react';
import { useId } from 'react';
import { Button } from '@/components/ui/button';
import {
    NativeSelect,
    NativeSelectOption,
} from '@/components/ui/native-select';
import { cn } from '@/lib/utils';

export const DEFAULT_PAGE_SIZE_OPTIONS = [10, 25, 50, 100];

export type DataTablePaginationProps<TData extends RowData> = {
    table: Table<TData>;
    pageSizeOptions?: number[];
    className?: string;
};

/** Keeps the current size selectable even when a page passes its own options. */
function withCurrentPageSize(options: number[], pageSize: number): number[] {
    if (options.includes(pageSize)) {
        return options;
    }

    return [...options, pageSize].sort((a, b) => a - b);
}

function summarise(
    rowCount: number,
    selectedCount: number,
    firstRow: number,
    lastRow: number,
): string {
    if (selectedCount > 0) {
        return `Выбрано ${selectedCount} из ${rowCount}`;
    }

    if (rowCount === 0) {
        return 'Нет строк';
    }

    return `${firstRow}–${lastRow} из ${rowCount}`;
}

/**
 * The footer below the table: what is on screen, how many rows a page holds and
 * the page controls.
 */
export function DataTablePagination<TData extends RowData>({
    table,
    pageSizeOptions = DEFAULT_PAGE_SIZE_OPTIONS,
    className,
}: DataTablePaginationProps<TData>) {
    const pageSizeId = useId();
    const { pageIndex, pageSize } = table.getState().pagination;
    const rowCount = table.getRowCount();
    const pageCount = table.getPageCount();
    const selectedCount = table.getSelectedRowModel().rows.length;

    // A server driven table that reports neither a row nor a page count cannot
    // say where the end is, so the jump-to-edge buttons have nowhere to go.
    const hasKnownPageCount = pageCount >= 0;

    const firstRow = pageIndex * pageSize + 1;
    const lastRow = Math.min(firstRow + pageSize - 1, rowCount);

    return (
        <div
            className={cn(
                'flex flex-wrap items-center justify-between gap-3',
                className,
            )}
        >
            <p className="text-muted-foreground text-sm tabular-nums">
                {summarise(rowCount, selectedCount, firstRow, lastRow)}
            </p>

            <div className="flex flex-wrap items-center gap-4">
                <div className="flex items-center gap-2">
                    <label
                        htmlFor={pageSizeId}
                        className="text-muted-foreground text-sm"
                    >
                        Строк на странице
                    </label>

                    <NativeSelect
                        id={pageSizeId}
                        size="sm"
                        value={pageSize}
                        onChange={(event) => {
                            table.setPageSize(Number(event.target.value));
                        }}
                    >
                        {withCurrentPageSize(pageSizeOptions, pageSize).map(
                            (option) => (
                                <NativeSelectOption key={option} value={option}>
                                    {option}
                                </NativeSelectOption>
                            ),
                        )}
                    </NativeSelect>
                </div>

                <div className="flex items-center gap-2">
                    <p className="text-muted-foreground text-sm tabular-nums">
                        Страница {pageIndex + 1}
                        {hasKnownPageCount
                            ? ` из ${Math.max(pageCount, 1)}`
                            : null}
                    </p>

                    <div className="flex items-center gap-1">
                        {hasKnownPageCount ? (
                            <Button
                                variant="outline"
                                size="icon-sm"
                                aria-label="К первой странице"
                                disabled={!table.getCanPreviousPage()}
                                onClick={() => {
                                    table.setPageIndex(0);
                                }}
                            >
                                <ChevronsLeftIcon aria-hidden="true" />
                            </Button>
                        ) : null}

                        <Button
                            variant="outline"
                            size="icon-sm"
                            aria-label="На предыдущую страницу"
                            disabled={!table.getCanPreviousPage()}
                            onClick={() => {
                                table.previousPage();
                            }}
                        >
                            <ChevronLeftIcon aria-hidden="true" />
                        </Button>

                        <Button
                            variant="outline"
                            size="icon-sm"
                            aria-label="На следующую страницу"
                            disabled={!table.getCanNextPage()}
                            onClick={() => {
                                table.nextPage();
                            }}
                        >
                            <ChevronRightIcon aria-hidden="true" />
                        </Button>

                        {hasKnownPageCount ? (
                            <Button
                                variant="outline"
                                size="icon-sm"
                                aria-label="К последней странице"
                                disabled={!table.getCanNextPage()}
                                onClick={() => {
                                    table.setPageIndex(pageCount - 1);
                                }}
                            >
                                <ChevronsRightIcon aria-hidden="true" />
                            </Button>
                        ) : null}
                    </div>
                </div>
            </div>
        </div>
    );
}

import type { RowData, Table } from '@tanstack/react-table';
import { SearchIcon } from 'lucide-react';
import {
    InputGroup,
    InputGroupAddon,
    InputGroupInput,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';

export type DataTableSearchProps<TData extends RowData> = {
    table: Table<TData>;
    placeholder?: string;
    /** Names the input, which shows no visible label. */
    label?: string;
    className?: string;
};

/**
 * Drives the table's global filter. Rows are matched in the browser unless the
 * table was built with `manualFiltering`, in which case `onGlobalFilterChange`
 * is where the request to the server belongs.
 */
export function DataTableSearch<TData extends RowData>({
    table,
    placeholder = 'Search',
    label = 'Search',
    className,
}: DataTableSearchProps<TData>) {
    const value = (table.getState().globalFilter ?? '') as string;

    return (
        <InputGroup className={cn('w-full sm:max-w-64', className)}>
            <InputGroupAddon>
                <SearchIcon aria-hidden="true" />
            </InputGroupAddon>

            <InputGroupInput
                type="search"
                value={value}
                aria-label={label}
                placeholder={placeholder}
                onChange={(event) => {
                    table.setGlobalFilter(event.target.value);
                }}
            />
        </InputGroup>
    );
}

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';

export type DataTableToolbarProps = {
    /** Filters and search, laid out from the start of the row. */
    children?: ReactNode;
    /** Buttons pushed to the end of the row — "Add", the column menu, an export. */
    actions?: ReactNode;
    className?: string;
};

/** The row above the table. Pass it to `DataTable` as its `toolbar`. */
export function DataTableToolbar({
    children,
    actions,
    className,
}: DataTableToolbarProps) {
    return (
        <div
            className={cn(
                'flex flex-wrap items-center justify-between gap-2',
                className,
            )}
        >
            <div className="flex flex-1 flex-wrap items-center gap-2">
                {children}
            </div>

            {actions ? (
                <div className="flex items-center gap-2">{actions}</div>
            ) : null}
        </div>
    );
}

import type { Column, RowData, Table } from '@tanstack/react-table';
import { SlidersHorizontalIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuCheckboxItem,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

export type DataTableViewOptionsProps<TData extends RowData> = {
    table: Table<TData>;
    label?: string;
};

/** A column names itself through `meta.label`, or through a plain string header. */
function columnLabel<TData extends RowData>(
    column: Column<TData, unknown>,
): string {
    const { meta, header } = column.columnDef;

    if (meta?.label) {
        return meta.label;
    }

    return typeof header === 'string' ? header : column.id;
}

/** Toggles which columns are visible. Renders nothing when none may be hidden. */
export function DataTableViewOptions<TData extends RowData>({
    table,
    label = 'Columns',
}: DataTableViewOptionsProps<TData>) {
    const columns = table
        .getAllLeafColumns()
        .filter((column) => column.getCanHide());

    if (columns.length === 0) {
        return null;
    }

    return (
        <DropdownMenu>
            <DropdownMenuTrigger
                render={
                    <Button variant="outline" size="sm">
                        <SlidersHorizontalIcon aria-hidden="true" />
                        {label}
                    </Button>
                }
            />

            <DropdownMenuContent align="end" className="w-44">
                {/* Base UI reads its group context from GroupLabel, so the
                    heading has to sit inside a group of its own. */}
                <DropdownMenuGroup>
                    <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
                </DropdownMenuGroup>

                <DropdownMenuSeparator />

                {columns.map((column) => (
                    <DropdownMenuCheckboxItem
                        key={column.id}
                        checked={column.getIsVisible()}
                        onCheckedChange={(visible) => {
                            column.toggleVisibility(visible);
                        }}
                    >
                        {columnLabel(column)}
                    </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

import type {
    Column,
    Header,
    Row,
    RowData,
    Table as TableInstance,
} from '@tanstack/react-table';
import { flexRender } from '@tanstack/react-table';
import type { KeyboardEvent, MouseEvent, ReactNode } from 'react';
import {
    Empty,
    EmptyDescription,
    EmptyHeader,
    EmptyTitle,
} from '@/components/ui/empty';
import { Skeleton } from '@/components/ui/skeleton';
import {
    Table,
    TableBody,
    TableCaption,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { cn } from '@/lib/utils';
import { DataTableColumnHeader } from './data-table-column-header';
import { DataTablePagination } from './data-table-pagination';
import type { DataTableAlign } from './types';
import type { UseDataTableOptions } from './use-data-table';
import { useDataTable } from './use-data-table';

const alignClasses: Record<DataTableAlign, string> = {
    start: 'text-left',
    center: 'text-center',
    end: 'text-right',
};

export type DataTableBaseProps<TData extends RowData> = {
    /** Rendered above the table — a search box, filters, bulk actions. */
    toolbar?: ReactNode;
    caption?: ReactNode;
    /** Swaps the rows for skeletons while the page waits for its data. */
    isLoading?: boolean;
    /** Defaults to a full page of skeletons. */
    skeletonRows?: number;
    /** Replaces the block shown when the table has no rows. */
    empty?: ReactNode;
    onRowClick?: (row: Row<TData>) => void;
    /** Hides the footer holding the page controls. */
    pagination?: boolean;
    pageSizeOptions?: number[];
    /** Drops the table's own border when the surface around it supplies one. */
    bordered?: boolean;
    fill?: boolean;
    footer?: ReactNode;
    className?: string;
};

type ProvidedDataTableProps<TData extends RowData> =
    DataTableBaseProps<TData> & {
        /** An existing instance from `useDataTable`, for pages that need its state outside the markup. */
        table: TableInstance<TData>;
    };

type ManagedDataTableProps<TData extends RowData> = DataTableBaseProps<TData> &
    UseDataTableOptions<TData> & { table?: undefined };

export type DataTableProps<TData extends RowData> =
    | ProvidedDataTableProps<TData>
    | ManagedDataTableProps<TData>;

function alignClassName<TData extends RowData>(
    column: Column<TData, unknown>,
): string {
    return alignClasses[column.columnDef.meta?.align ?? 'start'];
}

/** A width is only forced when the column asked for one. */
function widthStyle<TData extends RowData>(column: Column<TData, unknown>) {
    const { size } = column.columnDef;

    return size === undefined ? undefined : { width: size };
}

function ariaSort<TData extends RowData>(
    column: Column<TData, unknown>,
): 'ascending' | 'descending' | 'none' | undefined {
    if (!column.getCanSort()) {
        return undefined;
    }

    const sorted = column.getIsSorted();

    if (sorted === 'asc') {
        return 'ascending';
    }

    return sorted === 'desc' ? 'descending' : 'none';
}

/**
 * A clickable row must not swallow the controls inside it: a checkbox, a link
 * or a row action would otherwise fire and open the row at the same time.
 */
function startedOnControl(event: { target: EventTarget | null }): boolean {
    return (
        event.target instanceof Element &&
        event.target.closest(
            'a, button, input, select, textarea, [role="checkbox"], [role="menuitem"]',
        ) !== null
    );
}

function DataTableHeadCell<TData extends RowData>({
    header,
}: {
    header: Header<TData, unknown>;
}) {
    const { column } = header;
    const meta = column.columnDef.meta;

    if (header.isPlaceholder) {
        return <TableHead colSpan={header.colSpan} />;
    }

    const content = flexRender(column.columnDef.header, header.getContext());

    return (
        <TableHead
            colSpan={header.colSpan}
            aria-sort={ariaSort(column)}
            style={widthStyle(column)}
            className={cn(alignClassName(column), meta?.headerClassName)}
        >
            {column.getCanSort() ? (
                <DataTableColumnHeader column={column}>
                    {content}
                </DataTableColumnHeader>
            ) : (
                content
            )}
        </TableHead>
    );
}

function DataTableView<TData extends RowData>({
    table,
    toolbar,
    caption,
    isLoading = false,
    skeletonRows,
    empty,
    onRowClick,
    pagination = true,
    pageSizeOptions,
    bordered = true,
    fill = false,
    footer,
    className,
}: ProvidedDataTableProps<TData>) {
    const columns = table.getVisibleLeafColumns();
    const rows = table.getRowModel().rows;

    const { columnFilters, globalFilter } = table.getState();
    const isFiltered = columnFilters.length > 0 || Boolean(globalFilter);
    const isEmpty = !isLoading && rows.length === 0;

    const placeholderRowIds = Array.from(
        { length: skeletonRows ?? table.getState().pagination.pageSize },
        (_, index) => `skeleton-row-${index}`,
    );

    const handleRowClick = (event: MouseEvent, row: Row<TData>) => {
        if (startedOnControl(event)) {
            return;
        }

        onRowClick?.(row);
    };

    const handleRowKeyDown = (event: KeyboardEvent, row: Row<TData>) => {
        if (event.key !== 'Enter' && event.key !== ' ') {
            return;
        }

        if (startedOnControl(event)) {
            return;
        }

        event.preventDefault();
        onRowClick?.(row);
    };

    return (
        <div
            className={cn(
                'flex flex-col gap-3',
                fill && 'h-full min-h-0',
                className,
            )}
        >
            {toolbar}

            <div
                className={cn(
                    'flex flex-col overflow-hidden',
                    fill && 'min-h-0 flex-1',
                    bordered && 'rounded-xl border',
                )}
            >
                <Table
                    aria-busy={isLoading}
                    className={cn(fill && isEmpty && 'h-full')}
                    render={
                        fill ? (
                            <div className="h-full overflow-auto overscroll-none" />
                        ) : undefined
                    }
                >
                    {caption ? <TableCaption>{caption}</TableCaption> : null}

                    <TableHeader
                        className={cn(
                            'bg-background [&_th]:bg-secondary',
                            fill &&
                                'sticky top-0 z-10 [&_th]:border-b [&_tr]:border-b-0',
                        )}
                    >
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow
                                key={headerGroup.id}
                                className="hover:bg-transparent"
                            >
                                {headerGroup.headers.map((header) => (
                                    <DataTableHeadCell
                                        key={header.id}
                                        header={header}
                                    />
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>

                    <TableBody>
                        {isLoading ? (
                            placeholderRowIds.map((rowId) => (
                                <TableRow
                                    key={rowId}
                                    className="hover:bg-transparent"
                                >
                                    {columns.map((column) => (
                                        <TableCell key={column.id}>
                                            <Skeleton className="h-4 w-full" />
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        ) : rows.length === 0 ? (
                            <TableRow className="hover:bg-transparent">
                                <TableCell
                                    colSpan={columns.length}
                                    className="whitespace-normal p-0"
                                >
                                    {empty ?? (
                                        <Empty className="border-0">
                                            <EmptyHeader>
                                                <EmptyTitle>
                                                    Ничего не найдено
                                                </EmptyTitle>
                                                <EmptyDescription>
                                                    {isFiltered
                                                        ? 'Попробуйте изменить запрос или сбросить фильтры.'
                                                        : 'Здесь пока нет ни одной строки.'}
                                                </EmptyDescription>
                                            </EmptyHeader>
                                        </Empty>
                                    )}
                                </TableCell>
                            </TableRow>
                        ) : (
                            rows.map((row) => (
                                <TableRow
                                    key={row.id}
                                    data-state={
                                        row.getIsSelected()
                                            ? 'selected'
                                            : undefined
                                    }
                                    className={
                                        onRowClick
                                            ? 'cursor-pointer'
                                            : undefined
                                    }
                                    tabIndex={onRowClick ? 0 : undefined}
                                    onClick={
                                        onRowClick
                                            ? (event) => {
                                                  handleRowClick(event, row);
                                              }
                                            : undefined
                                    }
                                    onKeyDown={
                                        onRowClick
                                            ? (event) => {
                                                  handleRowKeyDown(event, row);
                                              }
                                            : undefined
                                    }
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell
                                            key={cell.id}
                                            style={widthStyle(cell.column)}
                                            className={cn(
                                                alignClassName(cell.column),
                                                cell.column.columnDef.meta
                                                    ?.cellClassName,
                                            )}
                                        >
                                            {flexRender(
                                                cell.column.columnDef.cell,
                                                cell.getContext(),
                                            )}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>

                {footer ? (
                    <div className="shrink-0 border-t bg-background">
                        {footer}
                    </div>
                ) : null}
            </div>

            {pagination ? (
                <DataTablePagination
                    table={table}
                    pageSizeOptions={pageSizeOptions}
                />
            ) : null}
        </div>
    );
}

function ManagedDataTable<TData extends RowData>({
    toolbar,
    caption,
    isLoading,
    skeletonRows,
    empty,
    onRowClick,
    pagination,
    pageSizeOptions,
    bordered,
    className,
    ...options
}: ManagedDataTableProps<TData>) {
    const table = useDataTable<TData>(options);

    return (
        <DataTableView
            table={table}
            toolbar={toolbar}
            caption={caption}
            isLoading={isLoading}
            skeletonRows={skeletonRows}
            empty={empty}
            onRowClick={onRowClick}
            pagination={pagination}
            pageSizeOptions={pageSizeOptions}
            bordered={bordered}
            className={className}
        />
    );
}

/**
 * Renders the table chrome around a TanStack instance: header cells with their
 * sort control and `aria-sort`, the rows, a loading and an empty state, and the
 * page controls. Builds the instance itself unless one is passed in.
 *
 * Column definitions stay plain: alignment, a hidden-column label and extra
 * classes travel in `meta`, and the sort affordance is added here rather than
 * in every column's `header`.
 */
export function DataTable<TData extends RowData>(props: DataTableProps<TData>) {
    if (props.table) {
        return <DataTableView {...props} />;
    }

    return <ManagedDataTable {...props} />;
}

import type { KeyboardEvent, ReactElement } from 'react';
import { useEffect, useRef, useState } from 'react';
import type { EditableCellStep } from '@/components/data-table/editable-cells';
import { useEditableCells } from '@/components/data-table/editable-cells';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';

const SAVED_FEEDBACK_MS = 600;

const STEP_BY_KEY: Record<string, EditableCellStep> = {
    ArrowDown: 'down',
    ArrowUp: 'up',
};

export type EditableCellProps = {
    rowId: string;
    columnId: string;
    value: string;
    onCommit: (value: string) => void;
    label: string;
    placeholder?: string;
    className?: string;
};

export function EditableCell({
    rowId,
    columnId,
    value,
    onCommit,
    label,
    placeholder,
    className,
}: EditableCellProps): ReactElement {
    const { editing, start, stop, step } = useEditableCells();
    const [draft, setDraft] = useState(value);
    const [saved, setSaved] = useState(false);
    const handled = useRef(false);

    const isEditing =
        editing?.rowId === rowId && editing?.columnId === columnId;

    useEffect(() => {
        if (isEditing) {
            setDraft(value);
            handled.current = false;
        }
    }, [isEditing, value]);

    useEffect(() => {
        if (!saved) {
            return;
        }

        const timer = setTimeout(() => setSaved(false), SAVED_FEEDBACK_MS);

        return () => clearTimeout(timer);
    }, [saved]);

    const commit = (next: string): void => {
        if (next !== value) {
            onCommit(next);
            setSaved(true);
        }
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
        if (event.key === 'Escape') {
            handled.current = true;
            setDraft(value);
            stop();

            return;
        }

        if (event.key === 'Enter') {
            handled.current = true;
            commit(draft);
            stop();

            return;
        }

        const direction =
            event.key === 'Tab'
                ? event.shiftKey
                    ? 'previous'
                    : 'next'
                : STEP_BY_KEY[event.key];

        if (!direction) {
            return;
        }

        event.preventDefault();
        handled.current = true;
        commit(draft);
        step({ columnId, rowId }, direction);
    };

    if (isEditing) {
        return (
            <Input
                aria-label={label}
                autoFocus
                className={className}
                onBlur={() => {
                    if (!handled.current) {
                        commit(draft);
                        stop();
                    }
                }}
                onChange={(event) => setDraft(event.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={placeholder}
                size="sm"
                value={draft}
            />
        );
    }

    return (
        <button
            aria-label={value ? undefined : `${label}, пусто`}
            className={cn(
                'flex h-8 w-full items-center rounded-md px-2 text-left transition-colors duration-500 hover:bg-accent sm:h-7',
                saved && 'bg-success/16 duration-0',
                className,
            )}
            data-saved={saved ? '' : undefined}
            onClick={() => start({ columnId, rowId })}
            type="button"
        >
            {value}
        </button>
    );
}

import type { ReactElement, ReactNode } from 'react';
import {
    createContext,
    useCallback,
    useContext,
    useMemo,
    useState,
} from 'react';

export type EditableCellAddress = {
    rowId: string;
    columnId: string;
};

export type EditableCellStep = 'next' | 'previous' | 'up' | 'down';

type EditableGrid = {
    editing: EditableCellAddress | null;
    start: (address: EditableCellAddress) => void;
    stop: () => void;
    step: (from: EditableCellAddress, step: EditableCellStep) => void;
};

const EditableCellsContext = createContext<EditableGrid | null>(null);

export function useEditableCells(): EditableGrid {
    const grid = useContext(EditableCellsContext);

    if (!grid) {
        throw new Error(
            'An editable cell has to sit inside an EditableCells provider.',
        );
    }

    return grid;
}

export type EditableCellsProps = {
    rowIds: string[];
    columnIds: string[];
    children: ReactNode;
};

export function EditableCells({
    rowIds,
    columnIds,
    children,
}: EditableCellsProps): ReactElement {
    const [editing, setEditing] = useState<EditableCellAddress | null>(null);

    const step = useCallback(
        (from: EditableCellAddress, direction: EditableCellStep) => {
            const rowIndex = rowIds.indexOf(from.rowId);
            const columnIndex = columnIds.indexOf(from.columnId);

            if (rowIndex === -1 || columnIndex === -1) {
                return;
            }

            if (direction === 'up' || direction === 'down') {
                const nextRow = rowIndex + (direction === 'down' ? 1 : -1);

                setEditing(
                    rowIds[nextRow] === undefined
                        ? null
                        : { columnId: from.columnId, rowId: rowIds[nextRow] },
                );

                return;
            }

            const flat = rowIndex * columnIds.length + columnIndex;
            const nextFlat = flat + (direction === 'next' ? 1 : -1);

            if (nextFlat < 0 || nextFlat >= rowIds.length * columnIds.length) {
                setEditing(null);

                return;
            }

            setEditing({
                columnId: columnIds[nextFlat % columnIds.length],
                rowId: rowIds[Math.floor(nextFlat / columnIds.length)],
            });
        },
        [rowIds, columnIds],
    );

    const grid = useMemo<EditableGrid>(
        () => ({
            editing,
            start: setEditing,
            step,
            stop: () => setEditing(null),
        }),
        [editing, step],
    );

    return (
        <EditableCellsContext.Provider value={grid}>
            {children}
        </EditableCellsContext.Provider>
    );
}

import type { Row, RowData } from '@tanstack/react-table';

export function facetedFilterFn<TData extends RowData>(
    row: Row<TData>,
    columnId: string,
    value: unknown,
): boolean {
    if (!Array.isArray(value) || value.length === 0) {
        return true;
    }

    return value.includes(String(row.getValue(columnId)));
}

